using Gtk 4.0;
using Adw 1;

template $CcPanelList: Adw.Bin {
  Stack stack {
    vhomogeneous: false;
    hhomogeneous: true;
    transition-type: slide_left_right;

    StackPage {
      name: "main";

      child: ListBox main_listbox {
        accessibility {
          label: _("Settings categories");
        }

        row-activated => $row_activated_cb();

        styles [
          "navigation-sidebar",
        ]
      };
    }

    StackPage {
      name: "search";

      child: ListBox search_listbox {
        row-activated => $search_row_activated_cb();
        keynav-failed => $cc_util_keynav_propagate_up();

        styles [
          "navigation-sidebar",
        ]

        [placeholder]
        Adw.StatusPage {
          icon-name: "edit-find-symbolic";
          title: _("No Results Found");
          description: _("Try a different search");

          styles [
            "compact",
          ]
        }
      };
    }
  }
}

using Gtk 4.0;
using Adw 1;

template $CcPanel: Adw.NavigationPage {
}

using Gtk 4.0;
using Adw 1;

template $CcWindow: Adw.ApplicationWindow {
  default-width: 980;
  default-height: 640;

  Adw.Breakpoint break_point {
    condition ("max-width: 550sp")

    setters {
      split_view.collapsed: true;
    }
  }

  content: Adw.NavigationSplitView split_view {
    notify::collapsed => $on_split_view_collapsed_changed_cb(template);

    sidebar: Adw.NavigationPage panel_list_page {
      title: _("Settings");

      child: Adw.ToolbarView {
        [top]
        Adw.HeaderBar {
          ToggleButton search_button {
            icon-name: "edit-find-symbolic";

            /* Translators: this is a verb. */
            tooltip-text: _("Search");
          }

          [end]
          MenuButton {
            icon-name: "open-menu-symbolic";
            menu-model: primary_menu;
            primary: true;
            tooltip-text: _("Main Menu");
          }
        }

        [top]
        SearchBar search_bar {
          search-mode-enabled: bind search_button.active bidirectional;

          SearchEntry search_entry {
            hexpand: true;
            placeholder-text: _("Search settings");
            activate => $search_entry_activate_cb(template);

            EventControllerKey {
              key-pressed => $search_entry_key_pressed_cb(template);
            }
          }
        }

        content: ScrolledWindow {
          hscrollbar-policy: never;

          $CcPanelList panel_list {
            search-mode: bind search_bar.search-mode-enabled no-sync-create bidirectional;
            search-query: bind search_entry.text no-sync-create;
            show-panel => $show_panel_cb(template);
          }
        };
      };
    };

    content: Adw.NavigationPage {
      child: Adw.NavigationView navigation {
      };
    };
  };
}

menu primary_menu {
  section {
    item {
      label: _("_Keyboard Shortcuts");
      action: "app.shortcuts";
    }

    item {
      label: _("_Help");
      action: "app.help";
    }

    item {
      label: _("_About Settings");
      action: "app.about";
    }
  }
}

using Gtk 4.0;
using Adw 1;

Adw.ShortcutsDialog shortcuts_dialog {
  Adw.ShortcutsSection {
    title: C_("shortcuts dialog", "General");

    Adw.ShortcutsItem {
      accelerator: "<Control>Q";
      title: C_("shortcuts dialog", "Quit");
    }

    Adw.ShortcutsItem {
      accelerator: "<Control>F";
      title: C_("shortcuts dialog", "Search");
    }

    Adw.ShortcutsItem {
      action-name: "app.help";
      title: C_("shortcuts dialog", "Show help");
    }

    Adw.ShortcutsItem {
      action-name: "app.shortcuts";
      title: C_("shortcuts dialog", "Keyboard shortcuts");
    }
  }

  Adw.ShortcutsSection {
    title: C_("shortcuts dialog", "Panels");

    Adw.ShortcutsItem {
      accelerator: "<Alt>Left";
      direction: ltr;
      title: C_("shortcuts dialog", "Go back to previous panel");
    }

    Adw.ShortcutsItem {
      accelerator: "<Alt>Right";
      direction: rtl;
      title: C_("shortcuts dialog", "Go back to previous panel");
    }
  }

  Adw.ShortcutsSection {
    title: C_("shortcuts dialog", "Search");

    Adw.ShortcutsItem {
      accelerator: "Escape";
      title: C_("shortcuts dialog", "Cancel search");
    }
  }
}
